// Helper function to count odd lower-case letters in the alphabet
function CountOddLowerCaseLetters(txt: string): int
    requires txt != null
    ensures 0 <= CountOddLowerCaseLetters(txt) <= txt.Length
{
    var count := 0;
    var i := 0;
    while (i < txt.Length)
        invariant 0 <= i <= txt.Length
        invariant count >= 0
    {
        if (txt[i] >= 'a' && txt[i] <= 'z' && (ord(txt[i]) % 2) == 1) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
